const PRODUCTION_WORKFLOW_PREFIX='LENSPIRE_DELIVERABLES_V1:';
const WEDDING_DELIVERABLES=['Raw Photos','Photo Retouching','Reels','Teaser','Cinematic Highlight','Full Length Video','Wedding Album'];
const PRODUCTION_TASK_STATUSES=['Unassigned','Assigned','In Progress','Submitted for Review','Revision Required','Approved','Sent to Client','Client Changes','Client Approved'];
const PRODUCTION_PRIORITIES=['Normal','High','Urgent'];
function normalizeProductionTask(item,index){const legacy=item.status==='Completed'?'Approved':item.status;return{id:item.id||`${Date.now()}-${index}`,name:item.name||'Deliverable',enabled:item.enabled!==false,quantity:Number(item.quantity||1),events:item.events||'',editor:item.editor||'',dueDate:item.dueDate||'',priority:item.priority||'Normal',status:PRODUCTION_TASK_STATUSES.includes(legacy)?legacy:(item.editor?'Assigned':'Unassigned'),driveLink:item.driveLink||'',revisionNotes:item.revisionNotes||'',revisionCount:Number(item.revisionCount||0),submittedAt:item.submittedAt||item.completedAt||'',submittedBy:item.submittedBy||item.completedBy||'',approvedAt:item.approvedAt||'',approvedBy:item.approvedBy||'',clientApprovedAt:item.clientApprovedAt||''};}
function normalizeGalleryLinks(saved){if(Array.isArray(saved?.galleryLinks)&&saved.galleryLinks.length)return saved.galleryLinks.filter(l=>l&&String(l.url||'').trim()).map(l=>({url:String(l.url).trim(),label:String(l.label||'View Gallery').trim().slice(0,80)||'View Gallery'}));const url=String(saved?.galleryUrl||'').trim();return url?[{url,label:String(saved?.galleryLabel||'View Gallery').trim().slice(0,80)||'View Gallery'}]:[];}function productionWorkflow(job){
  const raw=String(job?.notes||'');
  if(raw.startsWith(PRODUCTION_WORKFLOW_PREFIX)){try{const saved=JSON.parse(raw.slice(PRODUCTION_WORKFLOW_PREFIX.length));if(Array.isArray(saved.deliverables)){const existing=new Map(saved.deliverables.map(item=>[item.name,item]));const galleryLinks=normalizeGalleryLinks(saved);return{...saved,galleryLinks,deliverables:WEDDING_DELIVERABLES.map((name,index)=>normalizeProductionTask(existing.get(name)||{name,enabled:false},index))};}}catch(error){console.warn('Could not read production workflow',error);}}
  return {brief:raw,galleryLinks:[],deliverables:WEDDING_DELIVERABLES.map((name,index)=>normalizeProductionTask({name,enabled:['Raw Photos','Reels','Teaser','Cinematic Highlight','Full Length Video','Wedding Album'].includes(name)},index))};
}
function serializeProductionWorkflow(workflow){return PRODUCTION_WORKFLOW_PREFIX+JSON.stringify(workflow);}
function activeProductionTasks(job){return productionWorkflow(job).deliverables.filter(item=>item.enabled);}
function assignedProductionTasks(displayName=state.user?.displayName){const name=String(displayName||'').trim().toLowerCase(),tasks=[];(state.production||[]).forEach(job=>activeProductionTasks(job).forEach(item=>{if(String(item.editor||'').trim().toLowerCase()===name)tasks.push({job,item});}));return tasks;}
function productionTaskNeedsClientApproval(item){return['Reels','Teaser','Cinematic Highlight','Full Length Video','Wedding Album'].includes(item.name);}
function productionOverallStatus(job){if(job.stage==='Delivered')return'Delivered';const tasks=activeProductionTasks(job);if(!tasks.length||tasks.every(item=>!item.editor))return'Awaiting Assignment';if(tasks.some(item=>item.status==='Revision Required'||item.status==='Client Changes'))return'Revision Required';if(tasks.some(item=>item.status==='Submitted for Review'))return'Under Review';if(tasks.some(item=>item.status==='Sent to Client')||tasks.some(item=>productionTaskNeedsClientApproval(item)&&item.status==='Approved'))return'Client Approval';if(tasks.every(item=>productionTaskNeedsClientApproval(item)?item.status==='Client Approved':['Approved','Client Approved'].includes(item.status)))return'Ready for Delivery';return'In Production';}
function productionStageFromTasks(job){return({"Awaiting Assignment":productionJobShootCompleted(job)?'Shoot Completed':'Shoot Planning','In Production':'Editing','Under Review':'Client Approval','Revision Required':'Editing','Client Approval':'Client Approval','Ready for Delivery':'Ready for Delivery',Delivered:'Delivered'})[productionOverallStatus(job)]||'Editing';}
function productionTaskOverdue(item){return item.enabled&&item.dueDate&&!['Approved','Client Approved'].includes(item.status)&&item.dueDate<localDateKey();}
function postProductionEventType(event){return Boolean(String(event?.event_type||event?.eventType||'').trim());}
function weddingRelatedEvent(event){const type=String(event?.event_type||event?.eventType||'').trim().toLowerCase();return /\b(wedding|haldi|mehendi|mehndi|sangeet|reception|baraat|nikah|phera|vidai|cocktail)\b/.test(type)&&!/pre[-\s]?wedding/.test(type);}
function postProductionPaymentThreshold(event){return weddingRelatedEvent(event)?.9:.5;}
function postProductionCompletedEvents(job){const sourceEventId=job?.source_event_id||job?.sourceEventId||null;return(state.events||[]).filter(item=>(sourceEventId?sameId(item.id,sourceEventId):(sameId(item.booking_id,job?.booking_id)||String(item.client_name||item.customerName||'').trim()===String(job?.customerName||'').trim()))&&eventHasCompleted(item)&&postProductionEventType(item));}
function productionJobShootCompleted(job){return job.stage!=='Shoot Planning'||postProductionCompletedEvents(job).length>0;}

