async function login(event){
  event.preventDefault(); const form=event.currentTarget; const button=$('#loginSubmit');
  const username=form.username.value.trim(), password=form.password.value;
  button.disabled=true; button.innerHTML='Signing in…';
  try {
    const result=await ipcRenderer.invoke('authenticate-user',{username,password});
    if(!result.success){loginScreen(result.message);return;}
    state.user=result.user;
    state.salesOpen=false;state.operationsOpen=false;state.accountsOpen=false;state.postProductionOpen=false;
    try {
      const knownLoginNames=JSON.parse(localStorage.getItem('lenspire-login-names')||'{}');
      knownLoginNames[username.toLowerCase()]=result.user.displayName;
      localStorage.setItem('lenspire-login-names',JSON.stringify(knownLoginNames));
    } catch {}
    if(result.user.passwordUpgradeRequired){
      if(form.remember.checked)localStorage.setItem('lenspire-remembered-user',username);else localStorage.removeItem('lenspire-remembered-user');
      sessionStorage.setItem('lenspire-session','active');
      state.view='Settings';shell();toast('Security upgrade required · Set a strong password to continue');return;
    }
    const workspace=await ipcRenderer.invoke('get-workspace-data');
    applyWorkspace(workspace);
    if(form.remember.checked)localStorage.setItem('lenspire-remembered-user',username);else localStorage.removeItem('lenspire-remembered-user');
    sessionStorage.setItem('lenspire-session','active');
    shell();startWorkspaceSync();toast(result.migration?.synced?`Cloud restored · ${result.migration.synced} offline event change${result.migration.synced===1?'':'s'} synced`:result.migration?.imported?`Cloud ready · ${result.migration.imported} leads migrated`:result.migration?.offline?(result.migration.cached?'Offline mode · Event changes will sync after your next Cloud sign-in':'Cloud offline · No saved workspace on this computer'):'Welcome back, '+result.user.displayName.split(' ')[0]);
  } catch(error){loginScreen(error.message||'Unable to load the cloud workspace. Please try again.');console.error(error);}
}

async function logout(){try{await ipcRenderer.invoke('logout-user');}catch{}sessionStorage.removeItem('lenspire-session');state.user=null;state.view='Dashboard';state.query='';loginScreen();}

