async function importEventsFile(mode='upcoming'){
  const prefix=mode==='completed'?'Completed':'Upcoming',button=$(`#import${prefix}Events`),progress=(_event,data)=>{button.textContent=`Importing ${data.processed}/${data.total}…`;};
  button.disabled=true;button.textContent='Select Excel file…';ipcRenderer.on('events-import-progress',progress);
  try{const result=await ipcRenderer.invoke('import-events-file',mode);if(result.canceled){button.disabled=false;button.textContent='⇧ Import Excel';return;}applyWorkspace(result.workspace);renderView();const warning=result.importErrors?.length?` · First issue: ${result.importErrors[0]}`:'';toast(`${result.imported} ${mode==='completed'?'completed ':'upcoming '}events imported${result.skipped?` · ${result.skipped} rows skipped`:''}${result.skippedDuplicates?` (${result.skippedDuplicates} duplicates)`:''}${warning}`);}catch(error){button.disabled=false;button.textContent='⇧ Import Excel';toast(error.message||'Could not import events');console.error(error);}finally{ipcRenderer.removeListener('events-import-progress',progress);}
}
