function buildEventWhatsappMessage(event){
  const date=new Date(`${event.start_date}T00:00:00`),day=date.getDate(),suffix=(day%10===1&&day%100!==11)?'st':(day%10===2&&day%100!==12)?'nd':(day%10===3&&day%100!==13)?'rd':'th';
  let shortDate=`${day}${suffix} ${date.toLocaleDateString('en',{month:'short'})}`,fullDate=date.toLocaleDateString('en-GB',{day:'2-digit',month:'long',year:'numeric'}),weekDay=date.toLocaleDateString('en',{weekday:'long'});if(event.date_status==='TBD Month'){const month=date.toLocaleDateString('en',{month:'long',year:'numeric'});shortDate=`TBD ${month}`;fullDate=`TBD · ${month}`;weekDay='To be decided';}
  const time=event.start_time?new Date(`2000-01-01T${event.start_time}`).toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit'}):'Time to be confirmed';
  const crew=value=>String(value||'NA').split('; ').map(item=>item.replace(' · ',' ')).join(' + ');
  const lines=[`${shortDate} - ${event.event_type||'Event'} – ${event.couple_name||event.client_name||event.customerName||'Client'}`,'',`📞 Client / Contact: ${event.contact_no||'Not provided'}`,'','📍 Location & Venue:',event.city||'Venue to be confirmed','',`📅 Date: ${fullDate}`,`🗓 Day: ${weekDay}`,`⏰ Time: ${time}`,'','👥 Team Members:',`📸 Traditional Photographer: ${crew(event.photo)}`,`🎥 Traditional Videographer: ${crew(event.video)}`,`📷 Candid Photographer: ${crew(event.candid)}`,`🎬 Cinematographer: ${crew(event.cinematic)}`,`🛸 Drone Operator: ${crew(event.drone)}`,`🧑‍🤝‍🧑 Assistant: ${crew(event.assistant)}`];
  if(event.bts)lines.push(`📱 BTS: ${crew(event.bts)}`);
  const teamLabels=['Traditional Photographer','Traditional Videographer','Candid Photographer','Cinematographer','Drone Operator','Assistant','BTS'];
  for(let index=lines.length-1;index>=0;index--){if(teamLabels.some(label=>lines[index].includes(label))&&/:\s*(?:NA)?\s*$/i.test(lines[index]))lines.splice(index,1);}
  lines.push('','','💡 Notes:',event.notes||'No additional notes.','','🎯 Team Coordinators:','Govind Tiwari - 7757870959 - https://wa.me/7757870959','Sandeep Jadhav - 8976480490 - https://wa.me/8976480490','Pratiksha Pathak - 7709177580 - https://wa.me/7709177580','Aarzoo Singh - 9307846897 - https://wa.me/9307846897','','📸 *Guidelines for Photographers:*','• Always wear black colored plain outfits (T-shirt/Shirt and Jeans/Trousers).','• Avoid flashy colors, printed designs, or casual wear like shorts or slippers.','• Keep your attire clean and well-ironed.','• Arrive at least 30 minutes before event start time.','• Maintain respectful communication with clients and team.','• Do not argue with clients — report issues to coordinator.','• Avoid using mobile phones for personal use.','• Do not eat, smoke, or chew gum during the shoot.','• Follow Team Leader / Coordinator instructions.','• Support other team members.','• Do not share client photos/videos without permission.');
  return lines.join('\n');
}

