function showBackupPasswordModal() {
  return new Promise((resolve) => {
    const modal = document.createElement('div');
    modal.className = 'modal';
    modal.id = 'backupPasswordModal';
    modal.innerHTML = `
      <form class="modal-card" id="backupPasswordForm">
        <div class="modal-head">
          <div>
            <span>SECURITY</span>
            <h2>Backup Password</h2>
            <p>Create a strong password to encrypt this backup. It cannot be recovered if forgotten.</p>
          </div>
          <button type="button" data-close>×</button>
        </div>
        <div class="form-grid">
          <label class="full">Password<input name="password" type="password" required minlength="12" maxlength="128" placeholder="At least 12 characters"></label>
          <label class="full">Confirm Password<input name="confirm" type="password" required minlength="12" maxlength="128" placeholder="Repeat password"></label>
          <div class="form-error full" id="backupPasswordError"></div>
        </div>
        <div class="modal-actions">
          <button type="button" class="btn ghost" data-close>Cancel</button>
          <button type="submit" class="btn primary">Continue</button>
        </div>
      </form>
    `;
    document.body.appendChild(modal);
    setTimeout(() => modal.classList.add('show'), 10);
    const close = () => { modal.classList.remove('show'); setTimeout(() => modal.remove(), 180); resolve(null); };
    modal.querySelectorAll('[data-close]').forEach(b => b.onclick = close);
    const form = $('#backupPasswordForm');
    form.onsubmit = (e) => {
      e.preventDefault();
      const pwd = form.password.value;
      const confirm = form.confirm.value;
      const error = $('#backupPasswordError');
      if (pwd.length < 12) { error.textContent = 'Password must be at least 12 characters.'; return; }
      if (pwd !== confirm) { error.textContent = 'Passwords do not match.'; return; }
      modal.classList.remove('show');
      setTimeout(() => modal.remove(), 180);
      resolve(pwd);
    };
  });
}

