  const stage=$('#stageChart'),workload=$('#workloadChart'),trend=$('#deliveryTrendChart'),stageData=productionStageCounts(),hasStage=stageData.some(item=>item.count>0),workloadData=productionWorkload(),hasWorkload=workloadData.some(item=>item.count>0),trendData=productionMonthlyDeliveries(),palette=['#7367f0','#4f8cff','#f0a52b','#a77bf3','#31c887','#ef5b67','#20b8a6'];
