async function saveProductionWorkflow(job,workflow,extra={}){const virtual={...job,notes:serializeProductionWorkflow(workflow)},tasks=workflow.deliverables.filter(item=>item.enabled),editors=[...new Set(tasks.map(item=>item.editor).filter(Boolean))],dueDates=tasks.map(item=>item.dueDate).filter(Boolean).sort();return ipcRenderer.invoke('update-production-job',{jobId:job.id,data:{notes:virtual.notes,editor:editors.join(', '),dueDate:dueDates[0]||null,stage:productionStageFromTasks(virtual),...extra}});}
