function applyWorkspace(data){for(const key of ['leads','customers','bookings','events','payments','activities','productionActivities','salesTargets','salesExecutives','photographers','photographerDetails'])state[key]=data[key]||[];state.events=uniqueEvents(state.events.map(event=>{const dateStatus=event.date_status||event.dateStatus||'Confirmed',tbdMonth=event.tbd_month||event.tbdMonth||null;return{...event,date_status:dateStatus,tbd_month:tbdMonth,start_date:eventDateKey(event)};}));state.production=(data.production||[]).filter(postProductionEligible).map(job=>({...job,eventType:productionDisplayType(job)}));}

