function settingsView(el){
  const rules='minlength="12" maxlength="128"';
  const passwordSecurity=`<section class="panel" style="max-width:620px"><div class="panel-head"><div><h3>Change Your Password</h3><p>Use 12–128 characters with uppercase, lowercase, a number, and a symbol. You will be signed out on every device after the change.</p></div><span class="security-note">◇ Cloud secured</span></div><form id="changePasswordForm" class="form-grid" style="padding:20px"><label class="full">Current Password<input name="currentPassword" type="password" autocomplete="current-password" required></label><label class="full">New Password<input name="newPassword" type="password" ${rules} autocomplete="new-password" required></label><label class="full">Confirm New Password<input name="confirmPassword" type="password" ${rules} autocomplete="new-password" required></label><div class="form-error full" id="passwordChangeError"></div><div class="modal-actions full" style="padding:8px 0 0"><button class="btn primary" id="changePasswordButton">Change Password</button></div></form></section>`;
  const autoBackupSection=state.user?.role==='Administrator'?`<section class="panel" style="max-width:620px;margin-top:16px"><div class="panel-head"><div><h3>Auto Backup</h3><p>Automatically create an encrypted CRM backup every night.</p></div><span class="security-note">◇ Encrypted</span></div><form id="autoBackupForm" class="form-grid" style="padding:20px"><label class="full">Enable Auto Backup<select name="enabled"><option value="true">Yes</option><option value="false">No</option></select></label><label class="full">Backup Time<input name="time" type="time" value="02:00" required></label><label class="full">Backup Password<input name="password" type="password" required minlength="12" maxlength="128" placeholder="At least 12 characters"></label><label class="full">Confirm Password<input name="confirm" type="password" required minlength="12" maxlength="128" placeholder="Repeat password"></label><div class="form-error full" id="autoBackupError"></div><div class="modal-actions full" style="padding:8px 0 0"><button type="button" class="btn ghost" id="runAutoBackupNow">Run Now</button><button class="btn primary" id="saveAutoBackup">Save Settings</button></div></form></section>`:'';
  const portalSection=state.user?.isPlatformOwner?`<section class="panel" style="max-width:620px;margin-top:16px"><div class="panel-head"><div><h3>Client Portal URL</h3><p>Set your studio's web address that clients use to view galleries and approve deliveries. Use 2–64 characters: lowercase letters, numbers, and hyphens.</p></div><span class="security-note">◇ Public link</span></div><form id="studioSlugForm" class="form-grid" style="padding:20px"><label class="full">Studio URL Slug<input name="studioSlug" maxlength="64" placeholder="e.g. sunrisephotography" value="${esc(state.user?.organizationBranding?.studioSlug||'')}" style="font-family:monospace;font-size:11px"></label><div style="margin-top:8px;padding:8px 10px;border:1px solid var(--line);border-radius:6px;background:#0d1520;border-color:rgba(115,103,240,.3)"><span style="display:block;color:#7f8da1;font-size:8px;font-weight:700;text-transform:uppercase;letter-spacing:.4px">Portal URL</span><span id="portalUrlPreview" style="display:block;color:#a99fff;font-size:10px;font-family:monospace;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%;padding-top:4px">https://portal.lenspirecrm.com/${esc(state.user?.organizationBranding?.studioSlug||'—')}/your-client</span></div><div class="form-error full" id="studioSlugError"></div><div class="modal-actions full" style="padding:8px 0 0"><button class="btn primary" id="saveStudioSlug">Save Slug</button></div></form></section>`:'';
  el.innerHTML=`<section class="panel cloud-workspace-card" id="cloudWorkspaceCard"><div class="cloud-workspace-icon">☁</div><div><span>CLOUD WORKSPACE</span><h3 id="cloudWorkspaceStatus">Cloud: Checking… · ${esc(workspaceName())} Workspace</h3><p id="cloudWorkspaceDetail">Confirming this installation's cloud connection.</p></div><button class="btn ghost small" id="checkCloudWorkspace" type="button">Check again</button></section>${passwordSecurity}${portalSection}${autoBackupSection}`;
  $('#checkCloudWorkspace').onclick=refreshCloudWorkspaceStatus;
  refreshCloudWorkspaceStatus();
  const passwordForm=$('#changePasswordForm');if(passwordForm)passwordForm.onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,error=$('#passwordChangeError'),button=$('#changePasswordButton');error.textContent='';if(form.newPassword.value!==form.confirmPassword.value){error.textContent='New passwords do not match.';return;}button.disabled=true;button.textContent='Changing…';try{await ipcRenderer.invoke('change-cloud-password',{currentPassword:form.currentPassword.value,newPassword:form.newPassword.value});await ipcRenderer.invoke('logout-user');sessionStorage.removeItem('lenspire-session');state.user=null;state.view='Dashboard';loginScreen('Password changed successfully. Sign in with your new password.');}catch(problem){error.textContent=problem.message||'Could not change password.';button.disabled=false;button.textContent='Change Password';}};
  const autoForm=$('#autoBackupForm');if(autoForm){const errorEl=$('#autoBackupError');const saveBtn=$('#saveAutoBackup');const runBtn=$('#runAutoBackupNow');(async()=>{try{const settings=await ipcRenderer.invoke('get-autobackup-settings');autoForm.enabled.value=String(settings.enabled);autoForm.time.value=settings.time||'02:00';if(settings.password){autoForm.password.value=settings.password;autoForm.confirm.value=settings.password;}}catch{}})();saveBtn.onclick=async()=>{errorEl.textContent='';const pwd=autoForm.password.value,confirm=autoForm.confirm.value;if(pwd.length<12){errorEl.textContent='Password must be at least 12 characters.';return;}if(pwd!==confirm){errorEl.textContent='Passwords do not match.';return;}saveBtn.disabled=true;saveBtn.textContent='Saving…';try{await ipcRenderer.invoke('set-autobackup-settings',{enabled:autoForm.enabled.value==='true',time:autoForm.time.value,password:pwd});toast('Auto backup settings saved');}catch(problem){errorEl.textContent=problem.message||'Could not save settings.';}finally{saveBtn.disabled=false;saveBtn.textContent='Save Settings';}};runBtn.onclick=async()=>{runBtn.disabled=true;runBtn.textContent='Running…';try{await ipcRenderer.invoke('run-autobackup');toast('Auto backup started');}catch(problem){errorEl.textContent=problem.message||'Could not run backup.';}runBtn.disabled=false;runBtn.textContent='Run Now';}};
  const slugForm=$('#studioSlugForm');if(slugForm){const errorEl=$('#studioSlugError');const slugInput=slugForm.studioSlug;const preview=$('#portalUrlPreview');const updatePreview=()=>{const slug=slugInput.value.trim()||'—';preview.textContent=`https://portal.lenspirecrm.com/${slug}/your-client`;};slugInput.addEventListener('input',updatePreview);const saveBtn=slugForm.querySelector('#saveStudioSlug');saveBtn.onclick=async()=>{errorEl.textContent='';const slug=slugInput.value.trim();if(!slug){errorEl.textContent='Enter a studio URL slug.';return;}if(!/^[a-z0-9][a-z0-9-]*[a-z0-9]$|^[a-z0-9]{2,64}$/.test(slug)){errorEl.textContent='Slug must be 2–64 chars: lowercase letters, numbers, hyphens. Must start and end with a letter or number.';return;}if(slug.length>64){errorEl.textContent='Slug must be 64 characters or fewer.';return;}saveBtn.disabled=true;saveBtn.textContent='Saving…';try{await ipcRenderer.invoke('update-platform-organization-branding',{organizationId:state.user.organizationId,studioSlug:slug});if(state.user.organizationBranding)state.user.organizationBranding.studioSlug=slug;toast('Studio portal slug updated');}catch(problem){errorEl.textContent=problem.message||'Could not update studio slug.';}finally{saveBtn.disabled=false;saveBtn.textContent='Save Slug';}};
}
}

async function refreshCloudWorkspaceStatus(){
  const card=$('#cloudWorkspaceCard'),status=$('#cloudWorkspaceStatus'),detail=$('#cloudWorkspaceDetail'),button=$('#checkCloudWorkspace');if(!card||!status||!detail)return;
  card.classList.remove('connected','disconnected');status.textContent=`Cloud: Checking… · ${workspaceName()} Workspace`;detail.textContent='Confirming this installation\'s cloud connection.';if(button){button.disabled=true;button.textContent='Checking…';}
  try{const workspace=await ipcRenderer.invoke('get-workspace-data'),pending=Number(workspace?.pendingSync||0);if(workspace?.cloudStatus==='offline'){card.classList.add('disconnected');status.textContent=`Cloud: Offline · ${workspaceName()} Workspace`;detail.textContent=pending?`${pending} event change${pending===1?' is':'s are'} safely queued for sync.`:'Showing last synced data on this computer. New event changes will queue safely.';}else{card.classList.add('connected');status.textContent=`Cloud: Connected · ${workspaceName()} Workspace`;detail.textContent=pending?`${pending} event change${pending===1?' is':'s are'} waiting to sync.`:`Live sync available · Checked ${new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'})}`;}}
  catch(error){card.classList.add('disconnected');status.textContent=`Cloud: Disconnected · ${workspaceName()} Workspace`;detail.textContent='Connect this computer to the internet, then check again.';}
  finally{if(button){button.disabled=false;button.textContent='Check again';}}
}

