function weddingDateValues(value){try{const dates=JSON.parse(value||'[]');if(Array.isArray(dates))return dates;}catch{}return String(value||'').split(',').map(x=>x.trim()).filter(Boolean);}
function addWeddingDateField(value=''){const list=$('#weddingDates');if(!list)return;list.insertAdjacentHTML('beforeend',`<label>Wedding Date ${list.children.length+1}<input class="wedding-date-input" data-booking-field type="date" value="${esc(value)}"></label>`);toggleBookingFields($('#leadForm'));}
function toggleBookingFields(form){if(!form)return;const enabled=form.status.value==='Confirmed',section=$('#bookingFields');section.classList.toggle('locked',!enabled);section.querySelectorAll('[data-booking-field]').forEach(field=>field.disabled=!enabled);section.querySelectorAll('[data-booking-required]').forEach(field=>field.required=enabled);}
function toggleLeadStatusFields(form){toggleBookingFields(form);const lost=form.elements.lostReason;if(lost){const enabled=form.status.value==='Lost';lost.disabled=!enabled;lost.required=enabled;lost.closest('label').classList.toggle('field-locked',!enabled);}}
function leadActivityRows(leadId){const activities=state.activities.filter(activity=>Number(activity.lead_id)===Number(leadId));return activities.length?activities.map(activity=>`<article class="activity-row"><i class="activity-icon ${statusClass(activity.activity_type)}">${({Call:'☎',WhatsApp:'◉',Meeting:'□',Note:'✎','Status Change':'↻',Quotation:'▤','Lead Created':'＋','Follow-up':'◷'})[activity.activity_type]||'•'}</i><div><b>${esc(activity.activity_type)}</b><p>${esc(activity.description)}</p><small>${esc(activity.performed_by)} · ${dateTimeFmt(activity.created_at)}</small></div></article>`).join(''):'<div class="activity-empty">No activity recorded yet.</div>';}
function leadActivityTimeline(lead){return `<section class="lead-activity-section" id="leadActivitySection"><div class="activity-head"><div><span>LEAD HISTORY</span><h3>Activity Timeline</h3></div>${lead?`<div class="activity-composer" id="leadActivityForm"><select name="type"><option>Call</option><option>WhatsApp</option><option>Meeting</option><option>Note</option></select><input name="description" placeholder="Add activity details..."><button class="btn primary">Add Activity</button></div>`:'<small>Save the lead to begin its timeline.</small>'}</div><div class="activity-list" id="leadActivityList">${lead?leadActivityRows(lead.id):'<div class="activity-empty">Timeline starts after the lead is saved.</div>'}</div></section>`;}
async function saveLeadActivity(event,leadId){event.preventDefault();const container=event.currentTarget.closest?.('#leadActivityForm')||event.currentTarget,type=container.querySelector('[name=type]'),description=container.querySelector('[name=description]'),activity={type:type?type.value:'Note',description:description?description.value.trim():'',performedBy:state.user.displayName};if(!activity.description)return;try{applyWorkspace(await ipcRenderer.invoke('add-lead-activity',{leadId,activity}));$('#leadActivityList').innerHTML=leadActivityRows(leadId);if(description)description.value='';toast('Activity added');}catch(error){toast(error.message||'Could not add activity');}}
async function checkLeadDuplicate(form,leadId){const warning=$('#duplicateMobileWarning'),mobile=form.mobile.value.trim();if(!mobile){warning.textContent='';return;}try{const result=await ipcRenderer.invoke('check-duplicate-mobile',{mobile,excludeId:leadId||0});warning.textContent=result.duplicate?`Duplicate: ${result.lead.name} (${result.lead.code}) already uses this mobile number.`:'';warning.classList.toggle('visible',result.duplicate);}catch{warning.textContent='';}}
let quotationDriveState = { path: '', uploaded: false };
async function uploadQuotationToCloud(lead, filePath, name){
  if(!filePath || !name) return;
  if(quotationDriveState.path === filePath && quotationDriveState.uploaded) return;
  try{
    const result = await ipcRenderer.invoke('upload-quotation-drive', { cloudId: String(lead?.cloud_id || lead?.id || ''), leadId: lead?.id, filePath, name });
    if(result?.uploaded){ quotationDriveState = { path: filePath, uploaded: true }; toast('Quotation backed up to Google Drive'); }
    else if(result?.reason === 'offline'){ quotationDriveState = { path: filePath, uploaded: false }; toast('Quotation saved locally ' + sep + ' Sign in to LenspireCRM Cloud to enable Google Drive backup'); }
    else if(result?.reason === 'not-connected'){ quotationDriveState = { path: filePath, uploaded: false }; toast('Quotation saved locally ' + sep + ' Connect Google Drive in Settings to back it up'); }
    else if(result?.reason === 'missing-file'){ quotationDriveState = { path: filePath, uploaded: false }; toast('Quotation file not found on disk'); }
    else if(result?.reason === 'error'){ quotationDriveState = { path: filePath, uploaded: false }; toast('Quotation saved ' + sep + ' Drive backup failed: ' + (result.message || 'unknown error')); }
  }catch(err){ console.error('Drive upload skipped', err); }
}
async function selectQuotationFile(){try{const result=await ipcRenderer.invoke('select-quotation-file');if(result.canceled)return;const form=$('#leadForm');form.elements.quotationPath.value=result.path;form.elements.quotationName.value=result.name;$('#quotationName').textContent=result.name;$('#openQuotation').hidden=false;quotationDriveState={path:result.path,uploaded:false};toast('Quotation selected · Save the attachment or lead');}catch(err){toast(err.message||'Could not upload quotation');console.error(err);}}
async function saveQuotationAttachment(){const form=$('#leadForm'),leadId=form.dataset.leadId,path=form.elements.quotationPath.value,name=form.elements.quotationName.value;if(!path){toast('Upload a quotation first');return;}if(!leadId){toast('Quotation ready · Save the new lead to attach it');return;}try{applyWorkspace(await ipcRenderer.invoke('update-lead-attachment',{leadId,attachment:{path,name},performedBy:state.user.displayName}));$('#leadActivityList').innerHTML=leadActivityRows(leadId);uploadQuotationToCloud(state.leads.find(item=>sameId(item.id,leadId)),path,name);toast('Quotation attachment saved');}catch(err){toast(err.message||'Could not save attachment');console.error(err);}}
function closeAttachmentChoice(){const modal=$('#attachmentChoiceModal');if(modal){modal.classList.remove('show');setTimeout(()=>modal.remove(),180);}}
function showAttachmentChoice(path,name,leadId){$('#attachmentChoiceModal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal attachment-choice-modal" id="attachmentChoiceModal"><section class="attachment-choice-card"><div class="attachment-shimmer"></div><button class="attachment-close" id="closeAttachmentChoice" aria-label="Close">×</button><div class="attachment-orb">◇</div><span class="attachment-eyebrow">SAVED ATTACHMENT</span><h2>Client Quotation</h2><p>Choose how you want to access this attachment.</p><div class="attachment-file"><i>▤</i><div><b>${esc(name||'Quotation attachment')}</b><small>Stored locally or in the connected Google Drive</small></div><span>●</span></div><div class="attachment-choice-actions"><button class="view" id="viewAttachment"><i>◉</i><span><b>View</b><small>Open in the default application</small></span></button><button class="download" id="downloadAttachment"><i>⇩</i><span><b>Download</b><small>Save a copy to your computer</small></span></button></div><button class="attachment-cancel" id="cancelAttachmentChoice">Cancel</button></section></div>`);const modal=$('#attachmentChoiceModal');$('#closeAttachmentChoice').onclick=$('#cancelAttachmentChoice').onclick=closeAttachmentChoice;$('#viewAttachment').onclick=()=>performAttachmentAction('view',path,name,leadId);$('#downloadAttachment').onclick=()=>performAttachmentAction('download',path,name,leadId);setTimeout(()=>modal.classList.add('show'),10);}
async function performAttachmentAction(action,path,name,leadId){const buttons=document.querySelectorAll('.attachment-choice-actions button');buttons.forEach(button=>button.disabled=true);try{const result=await ipcRenderer.invoke('open-quotation-attachment',{path,name,leadId,action});if(result.action==='downloaded')toast('Quotation downloaded');if(result.source==='cloud')toast('Quotation opened from Google Drive');if(result.action!=='canceled')closeAttachmentChoice();else buttons.forEach(button=>button.disabled=false);}catch(err){if(leadId&&String(err.message||'').includes('upload the quotation again')&&confirm('The original quotation is unavailable. Select the file now to repair this attachment?')){try{const selected=await ipcRenderer.invoke('select-quotation-file');if(!selected.canceled){applyWorkspace(await ipcRenderer.invoke('update-lead-attachment',{leadId,attachment:{path:selected.path,name:selected.name},performedBy:state.user.displayName}));const lead=state.leads.find(item=>sameId(item.id,leadId));await uploadQuotationToCloud(lead,selected.path,selected.name);const opened=await ipcRenderer.invoke('open-quotation-attachment',{path:selected.path,name:selected.name,leadId,action});if(opened.action==='downloaded')toast('Quotation downloaded');else toast('Quotation repaired and opened');closeAttachmentChoice();return;}}catch(repairError){toast(repairError.message||'Could not repair attachment');console.error(repairError);}}buttons.forEach(button=>button.disabled=false);toast(err.message||'Could not open attachment');console.error(err);}}
function openQuotationAttachment(){const form=$('#leadForm'),path=form.elements.quotationPath.value,name=form.elements.quotationName.value;if(!path){toast('No quotation attachment saved');return;}showAttachmentChoice(path,name,form.dataset.leadId);}
