  el.querySelectorAll('[data-payment-history]').forEach(function(button){button.insertAdjacentHTML('afterend','<button class="btn ghost small" data-client-portal="'+button.dataset.paymentHistory+'" title="Create a private client portal link">Client Portal</button>');});
